window.LOOP_DECK_ES = Object.assign(window.LOOP_DECK_ES || {}, {"Let’s take every Bavaria experience to the Loop Digital ecosystem in Colombia.":"Llevemos cada experiencia de Bavaria al ecosistema de Loop Digital en Colombia."});

window.LOOP_DECK_ES = Object.assign(window.LOOP_DECK_ES || {}, {"Through a comprehensive ecosystem of premium advertising formats, we help brands build a consistent and relevant presence across the digital landscape — expanding reach, strengthening brand recall, and building a cohesive omnichannel positioning.":"A través de un ecosistema completo de formatos publicitarios premium, ayudamos a las marcas a construir una presencia consistente y relevante en el entorno digital, activando múltiples puntos de contacto con audiencias de alto valor para expandir el alcance, fortalecer la recordación de marca y construir un posicionamiento sólido y coherente de manera omnicanal."});

