window.LOOP_DECK_ES = Object.assign(window.LOOP_DECK_ES || {}, {"HOW WE ACTIVATE":"CÓMO ACTIVAMOS","TECHNOLOGICAL CAPABILITIES":"CAPACIDADES TECNOLÓGICAS","Our ID Fusion technology uses multiple signals and identifiers to recognize and connect the same user across different devices, enabling:":"Nuestra tecnología de ID Fusion utiliza múltiples señales e identificadores tecnológicos para reconocer y conectar a un mismo usuario entre diferentes dispositivos, permitiendo:","Identify a user across multiple devices.":"Identificar a un usuario a través de múltiples dispositivos.","Measure exposure across devices and control frequency globally.":"Medir si un usuario fue impactado en diferentes dispositivos y controlar la frecuencia a nivel global.","Accompany the user with different messages along their journey.":"Acompañar al usuario con diferentes mensajes a lo largo de su journey.","Know whether an exposed user visited the site, registered or made an FTD.":"Identificar si un usuario expuesto visitó el sitio, se registró o realizó un FTD.","ID FUSION · OMNICHANNEL":"ID FUSION · OMNICANAL","· SMART TV":"· SMART TV","· TOTEM":"· TÓTEM","VIP ACCESS →":"ACCESO VIP →","· DESKTOP":"· ESCRITORIO","NOW PLAYING · AD":"EN VIVO · ANUNCIO","· MOBILE":"· MÓVIL","ONE USER · MULTIPLE TOUCHPOINTS":"UN USUARIO · MÚLTIPLES PUNTOS DE CONTACTO","IDENTIFY · MEASURE · SEQUENCE · CONVERT":"IDENTIFICAR · MEDIR · SECUENCIAR · CONVERTIR"});
